using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
using DesignThix.Core.Media;

namespace DesignThix.Tests.Core;

/// <summary>
/// The Deko pack (<c>wwwroot/builtin/deko</c>, generated by <c>tools/deko/build.js</c>): every file has to pass the sanitiser unchanged (the generator writes exactly the
/// form <see cref="SvgSafe"/> writes: one line, <c>&lt;tag a="b" /&gt;</c> for empty elements, no comments, no XML declaration), has an exact numeric viewBox that equals
/// width and height (so the intrinsic aspect ratio is exact), a valid unique key and a name of the form "Group · Name".
/// </summary>
public sealed partial class DekoPackTests
{
    private static readonly string[] Groups = ["Rahmen", "Ornamente", "Blumen & Blätter", "Konfetti & Ballons", "Herzen", "Bänder & Siegel", "Trenner", "Ecken", "Muster", "Sterne", "Formen"];

    private sealed record Entry(string Key, string Name, string Category, string File, string[] Tags);

    [GeneratedRegex(@"^[a-z0-9][a-z0-9_-]{0,63}$")]
    private static partial Regex KeyPattern();

    [GeneratedRegex(@"^<svg viewBox=""0 0 (?<w>\d+) (?<h>\d+)"" width=""(?<w2>\d+)"" height=""(?<h2>\d+)"" xmlns=""http://www\.w3\.org/2000/svg"">")]
    private static partial Regex RootPattern();

    private static (string Root, List<Entry> All, List<Entry> Deko) Load()
    {
        var www = RepoFiles.WwwRoot();
        var root = Path.Combine(www, "builtin");
        var all = JsonSerializer.Deserialize<List<Entry>>(File.ReadAllText(Path.Combine(root, "builtin.json")), new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;
        return (root, all, all.Where(e => e.Category == "Deko").ToList());
    }

    private static string Diff(byte[] a, byte[] b)
    {
        var i = 0;
        while (i < a.Length && i < b.Length && a[i] == b[i])
        {
            i++;
        }

        string Part(byte[] x) => System.Text.Encoding.UTF8.GetString(x, Math.Max(0, i - 40), Math.Min(100, x.Length - Math.Max(0, i - 40)));
        return $"at {i}: source '{Part(a)}' vs clean '{Part(b)}'";
    }

    [Fact]
    public void The_pack_has_at_least_120_entries_with_valid_unique_keys_and_names()
    {
        var (_, all, deko) = Load();
        Assert.True(deko.Count >= 120, $"only {deko.Count} Deko entries");
        Assert.Equal(all.Count, all.Select(e => e.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count());
        foreach (var e in deko)
        {
            Assert.Matches(KeyPattern(), e.Key);
            Assert.StartsWith("deko-", e.Key);
            Assert.StartsWith("deko/", e.File);
            var parts = e.Name.Split(" · ");
            Assert.True(parts.Length == 2 && parts[1].Trim().Length > 0, $"name of {e.Key}: {e.Name}");
            Assert.Contains(parts[0], Groups);
            Assert.NotEmpty(e.Tags);
        }

        // every group is there with a fair number of pieces
        foreach (var group in Groups)
        {
            Assert.True(deko.Count(e => e.Name.StartsWith(group + " · ", StringComparison.Ordinal)) >= 6, $"group {group} is too small");
        }
    }

    [Fact]
    public void Every_file_passes_the_sanitiser_unchanged_and_has_an_exact_view_box()
    {
        var (root, _, deko) = Load();
        foreach (var e in deko)
        {
            var path = Path.Combine(root, e.File.Replace('/', Path.DirectorySeparatorChar));
            Assert.True(File.Exists(path), $"{e.Key}: {e.File} is missing");
            var bytes = File.ReadAllBytes(path);
            var result = SvgSafe.Sanitize(bytes);
            Assert.True(result.Ok, $"{e.Key}: {result.Error}");
            Assert.Empty(result.Removed);
            Assert.True(bytes.AsSpan().SequenceEqual(result.Bytes), $"{e.Key}: the sanitiser changes the file {Diff(bytes, result.Bytes!)}");

            var text = System.Text.Encoding.UTF8.GetString(bytes);
            var root_ = RootPattern().Match(text);
            Assert.True(root_.Success, $"{e.Key}: the root element is not in the expected form");
            Assert.Equal(root_.Groups["w"].Value, root_.Groups["w2"].Value);
            Assert.Equal(root_.Groups["h"].Value, root_.Groups["h2"].Value);
            Assert.Equal(int.Parse(root_.Groups["w"].Value, CultureInfo.InvariantCulture), result.Width);
            Assert.Equal(int.Parse(root_.Groups["h"].Value, CultureInfo.InvariantCulture), result.Height);
            Assert.DoesNotContain("<text", text, StringComparison.Ordinal);
            Assert.DoesNotContain("<style", text, StringComparison.Ordinal);
            Assert.DoesNotContain("<script", text, StringComparison.Ordinal);
            Assert.DoesNotContain("data:", text, StringComparison.Ordinal);
            Assert.DoesNotContain("xlink", text, StringComparison.Ordinal);
            Assert.True(text.Count(c => c == '\n') == 0, $"{e.Key}: more than one line");
        }
    }

    [Fact]
    public void The_folder_is_small_and_has_a_licence_note_and_no_stray_files()
    {
        var (root, _, deko) = Load();
        var folder = Path.Combine(root, "deko");
        var files = Directory.GetFiles(folder);
        var size = files.Sum(f => new FileInfo(f).Length);
        Assert.True(size < 3L * 1024 * 1024, $"the Deko folder is {size / 1024} KB");
        Assert.True(File.Exists(Path.Combine(folder, "LICENSE.txt")));
        var listed = deko.Select(e => Path.GetFileName(e.File)).ToHashSet(StringComparer.Ordinal);
        foreach (var f in files.Select(Path.GetFileName))
        {
            Assert.True(f == "LICENSE.txt" || listed.Contains(f!), $"{f} is not in builtin.json");
        }
    }

    [Fact]
    public void Colours_of_a_drawing_share_one_drawing_and_the_names_carry_the_colour()
    {
        var (_, _, deko) = Load();
        // a name with a colour in brackets has a key that ends with the colour word
        var colours = new Dictionary<string, string>
        {
            ["Gold"] = "gold", ["Rosé"] = "rose", ["Salbei"] = "salbei", ["Navy"] = "navy", ["Schwarz"] = "schwarz", ["Weiß"] = "weiss", ["Bordeaux"] = "bordeaux", ["Tanne"] = "tanne", ["Warnung"] = "warn",
            ["Bunt"] = "bunt", ["Pastell"] = "pastell", ["Herbst"] = "herbst", ["Boho"] = "boho",
        };
        var match = Regex.Matches(string.Join('\n', deko.Select(e => e.Name)), @"\((?<c>[^)]+)\)$", RegexOptions.Multiline);
        Assert.NotEmpty(match);
        foreach (var e in deko)
        {
            var m = Regex.Match(e.Name, @"\((?<c>[^)]+)\)$");
            if (m.Success)
            {
                Assert.True(colours.TryGetValue(m.Groups["c"].Value, out var slug), $"unknown colour in {e.Name}");
                Assert.EndsWith("-" + slug, e.Key);
            }
        }
    }
}
